                'title' => 'Mengembangkan Sistem PPDB Digital Intelligence yang terintegrasi  dengan Smart Quick Analytics, Smart Finder Student, dan  Virtual Admin',
                'description' => 'Mengembangkan Sistem PPDB Digital Intelligence yang terintegrasi \ndengan Smart Quick Analytics, Smart Finder Student, dan \nVirtual Admin sehingga 100% calon siswa memiliki \nStudent Success Profile digital dan seluruh data PPDB dapat \ndianalisis secara real-time pada Juni 2027.\n1. Smart Quick Analitik yang meliputi :\n    a. Analisa Potensi & Bakat\n    b. Analisa Tumbuh Kembang\n    c. Analisa Gaya Belajar\n    d. Analisa Pasar\n    e. Top 20 Hasil Test\n    f. Top 20 Nilai Raport\n\n2. Smart Finder Student (Hasil Analisa Berdasarkan Anak) :\n    a. Data Diri dan Orangtua (Tempat Kerja dan Penghasilan)\n    b. Ringkasan Akademik (Hasil Psikotest, Observasi, Litnum, \n         Wawancara Siswa, Wawancara Orangtua, Raport dan Prestasi)\n    c. RIngkasan Riwayat Kesehatan \n    d.Analisa Siswa (Analisa Minat & Bakat, Analisa Gaya Belajar, \n        Analisa Tumbuh Kembang)\n    e. Potensi Pengembangan Diri (Psikometri)\n\n3. Virtual Admin (Chat Bot)\n\n4. Form waiting list siswa, form daftar hadir sebelum event ppdb, \n    form keminatan masuk avicenna setelah event ppdb dan form \n    survei persektif positif dan kepuasan orangtua',
